import {activeMessages,presenceLabel} from './chat-model.mjs';
const demo=['localhost','127.0.0.1'].includes(location.hostname)&&new URL(location.href).searchParams.get('preview')==='1';
const make=(tag,text,cls)=>{const n=document.createElement(tag);if(text)n.textContent=text;if(cls)n.className=cls;return n};
const key='card-chat-local-preview-v2';let chats=[];if(demo){try{chats=JSON.parse(localStorage.getItem(key)||'null')}catch{}if(!Array.isArray(chats))chats=[{id:'sample-1',name:'Sample collector',online:true,read:0,messages:[{text:'Would you trade No. 83 for No. 92?',at:Date.now(),mine:false}]},{id:'sample-2',name:'Sample trader',online:false,lastSeen:new Date(Date.now()-42*60000).toISOString(),read:Date.now(),messages:[{text:'Thanks! Let’s arrange a card exchange.',at:Date.now()-3600000,mine:false}]}]}
let blockedIds=[];if(demo)try{const saved=JSON.parse(localStorage.getItem(key+'-blocks')||'[]');if(Array.isArray(saved))blockedIds=saved}catch{}
function save(){if(demo)try{localStorage.setItem(key,JSON.stringify(chats));localStorage.setItem(key+'-blocks',JSON.stringify(blockedIds))}catch{}}
function cleanup(){for(const c of chats)c.messages=activeMessages(c.messages||[]);save()}
cleanup();const timer=setInterval(()=>{const count=chats.reduce((n,c)=>n+c.messages.length,0);cleanup();badge();if(count!==chats.reduce((n,c)=>n+c.messages.length,0)&&!panel.hidden&&!body.querySelector('textarea')?.value){if(current)conversation(current,false);else inbox()}},60000);window.addEventListener('pagehide',()=>clearInterval(timer),{once:true});
const launch=make('button',null,'message-launcher');launch.type='button';launch.setAttribute('aria-label','Open messages');launch.setAttribute('aria-expanded','false');launch.setAttribute('aria-controls','message-panel');const label=make('span','Messages'),notification=make('span',null,'message-notification');launch.append(label,notification);
const panel=make('section',null,'message-panel');panel.id='message-panel';panel.hidden=true;panel.setAttribute('role','region');panel.setAttribute('aria-label','Messages');const head=make('header',null,'message-head'),title=make('h2','Messages'),actions=make('div',null,'row'),back=make('button','‹','btn secondary'),minimize=make('button','−','btn secondary'),close=make('button','×','btn secondary');for(const [b,name] of [[back,'Back to conversations'],[minimize,'Minimize messages'],[close,'Close messages']]){b.type='button';b.setAttribute('aria-label',name)}back.hidden=true;actions.append(minimize,close);head.append(back,title,actions);const body=make('div',null,'message-body'),foot=make('footer',demo?'Local preview · messages expire after 7 days':'Messages expire after 7 days once messaging is connected.','message-footer');panel.append(head,body,foot);document.body.append(launch,panel);
let current=null;function unread(c){return !c.blocked&&c.messages.some(m=>!m.mine&&m.at>(c.read||0))}function badge(){const n=chats.filter(unread).length;notification.hidden=!n;notification.textContent=String(n);launch.setAttribute('aria-label',n?'Open messages, '+n+' unread chats':'Open messages')}
function toggle(value){panel.hidden=!value;launch.hidden=value;launch.setAttribute('aria-expanded',String(value));if(value)close.focus();else launch.focus()};launch.onclick=()=>{inbox();toggle(true)};close.onclick=minimize.onclick=()=>toggle(false);panel.addEventListener('keydown',e=>{if(e.key==='Escape')toggle(false)});
function dot(online){const d=make('span',null,'presence-dot '+(online===true?'online':online===false?'offline':'unknown'));d.setAttribute('role','img');d.setAttribute('aria-label',online===true?'Online':online===false?'Offline':'Status unavailable');return d}
function inbox(){current=null;title.textContent='Messages';back.hidden=true;body.replaceChildren();cleanup();badge();if(!demo){body.append(make('h3','Your conversations'),make('p','Live messaging is not connected yet.','caption'));return}for(const c of chats){const row=make('button',null,'message-conversation'+(unread(c)?' unread':'')),line=make('span',null,'message-person');row.type='button';line.append(dot(c.online),make('strong',c.name));if(unread(c))line.append(make('span','New','unread-label'));row.append(line,make('span',c.blocked?'Blocked':c.messages.at(-1)?.text||'No messages','caption'));row.onclick=()=>conversation(c);body.append(row)}if(!chats.length)body.append(make('h3','No conversations'),make('p','Choose Chat beside a player to start.','caption'))}
function conversation(c,markRead=true){current=c;if(markRead){c.read=Date.now();save()}badge();title.replaceChildren(dot(c.online),document.createTextNode(c.name));back.hidden=false;body.replaceChildren(make('p',presenceLabel(c.online,c.lastSeen),'caption'));const tools=make('div',null,'message-chat-tools'),del=make('button','Delete chat','btn secondary'),block=make('button',c.blocked?'Unblock':'Block','btn secondary');del.type=block.type='button';del.onclick=()=>{chats=chats.filter(x=>x.id!==c.id);save();inbox()};block.onclick=()=>{c.blocked=!c.blocked;blockedIds=c.blocked?[...new Set([...blockedIds,c.id])]:blockedIds.filter(id=>id!==c.id);save();conversation(c)};tools.append(del,block);body.append(tools);const list=make('div',null,'message-thread');for(const m of c.messages){const bubble=make('div',null,'message-bubble'+(m.mine?' mine':''));bubble.append(make('p',m.text),make('small',m.mine?'Sent locally':'Read'));list.append(bubble)}if(!c.messages.length)list.append(make('p','No messages yet.','caption'));body.append(list);if(c.blocked){body.append(make('p','This person is blocked. Unblock to chat again.','notice'));return}const form=make('form',null,'message-compose'),input=make('textarea'),send=make('button','Send','btn');input.placeholder='Write a message…';input.setAttribute('aria-label','Message');input.maxLength=1000;input.rows=2;send.type='submit';form.append(input,send);form.onsubmit=e=>{e.preventDefault();const text=input.value.trim();if(!text)return;c.messages.push({text,at:Date.now(),mine:true});save();conversation(c);body.querySelector('textarea')?.focus()};body.append(form)}back.onclick=inbox;
window.addEventListener('card-chat-open',e=>{if(!demo){inbox();toggle(true);return}const p=e.detail;let c=chats.find(c=>c.id===p.id);if(!c){c={id:p.id,name:p.name,online:p.online,lastSeen:p.last_seen,read:Date.now(),messages:[],blocked:blockedIds.includes(p.id)};chats.push(c);save()}if(p.giftText&&!c.blocked){c.messages.push({text:String(p.giftText).slice(0,1000),at:Date.now(),mine:true});save()}conversation(c);toggle(true)});inbox();
